sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        // 1. Initialize your existing REST message and method

        //sm.setStringParameterNoEscape('apiKey', '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');
        var sm = new sn_ws.RESTMessageV2('Open AI Integration', 'AI Input');

        // 2. Build the strict JSON schema prompt injects our live sensor data
        var systemPrompt = "You are an industrial automation parser. Review vault telemetry logs. Respond STRICTLY in valid raw JSON matching this schema: {\"safety_level\":\"CRITICAL\"|\"WARNING\"|\"NORMAL\",\"root_cause\":\"string\",\"remediation\":\"string\",\"pump_override\":true|false}. Do not wrap in markdown or backticks.";

        var userContent = current.description.toString();
        var jsonPayload = {
            "model": "gpt-4o-mini",
            "messages": [{
                    "role": "system",
                    "content": systemPrompt
                },
                {
                    "role": "user",
                    "content": userContent
                }
            ],
            "temperature": 0.0 // Low temperature guarantees deterministic enterprise output
        };
        sm.setRequestBody(JSON.stringify(jsonPayload));

        // 3. Execute call and benchmark round-trip performance latency
        var startTime = new Date().getTime();
        var response = sm.execute();
        var endTime = new Date().getTime();

        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();
        // 4. Parse response on HTTP success
        if (httpStatus == 200) {
            // Log metrics and raw audit trail to your custom metadata fields
            current.execution_latency = endTime - startTime;
            current.ai_json_output = responseBody;

            var parsedJson = JSON.parse(responseBody);
            // Sanitize potential string formatting artifacts dynamically
            var aiText = parsedJson.choices[0].message.content.replace(/```json|```/g, "").trim();
            var analysis = JSON.parse(aiText);

            // 5. Execute core workflow orchestration rules based on AI parsing
            current.analysis = "=== AI REAL-TIME ANALYSIS ENGINE ===\n" +
                "Root Cause: " + analysis.root_cause + "\n" +
                "Recommended Mitigation: " + analysis.remediation + "\n" +
                "Automated Pump Override Active: " + analysis.pump_override;

            // If AI diagnoses severe flooding risk, auto-escalate ticket priority
            if (analysis.safety_level === "CRITICAL") {
                current.impact = 1;
                current.urgency = 1; // Pushes record to Priority 1 Critical
                current.short_description = "[⚠️ AI ESCALATION] " + current.short_description;
            } else if (analysis.safety_level === "WARNING") {
                current.urgency = 2; // Medium-high priority
            }

            // Commit changes to the active background thread
            current.update();
        } else {
            gs.error("AI Vault Processor HTTP Error: " + httpStatus + " - " + responseBody);
        }
    } catch (ex) {
        gs.error("AI Vault Processor Exception thrown: " + ex.getMessage());
    }
})(current, previous);
